usage.code:
import { createDevtoolsClient } from '@axonpack/expo-devtools';

export const devtools = createDevtoolsClient({
  theme: 'dark',
  network: { http: true, websocket: true, sse: true },
  console: { capture: true, repl: true },
});

// Guard this one call and the whole package stays dark in production.
devtools.init();
